type Kind="user"|"internet"|"app"|"data"|"security"|"file"|"network"|"storage"|"ai"|"message"|"monitor"|"compute";
type Node={label:string;sub:string;kind?:Kind;icon?:string};
type Layer={title:string;nodes:Node[]};
type Arch={title:string;note:string;layers:Layer[];reference:string};
type Entry={service:string;category:string;alias?:string};
const P=(label:string,sub:string,kind:Kind):Node=>({label,sub,kind});
const W=(label:string,sub:string,icon?:string):Node=>({label,sub,icon});
const L=(title:string,...nodes:Node[]):Layer=>({title,nodes});
const A=(title:string,note:string,reference:string,...layers:Layer[]):Arch=>({title,note,reference,layers});

const entries:Entry[]=aipScope.flatMap(category=>category.services.map(service=>({service,category:category.title,alias:guideAliases[service]})));
const normalize=(v:string)=>v.toLowerCase().replace(/\([^)]*\)/g," ").replace(/\b(amazon|aws)\b/g," ").replace(/[^a-z0-9]+/g," ").trim();
const resolveEntry=(name:string)=>entries.find(x=>normalize(x.service)===normalize(name)||!!x.alias&&normalize(x.alias)===normalize(name));
export const aipDetailServices=new Set(entries.flatMap(x=>[x.service,x.alias].filter(Boolean) as string[]));
export const hasAipLearningDetails=(name:string)=>!!resolveEntry(name);
export const getAipLearningMeta=(name:string)=>{const e=resolveEntry(name);return e?{service:e.service,category:e.category,sections:["overview","concepts","architectures","use-cases","security","optimization","cost-models","comparison","memory-hook"]}:null};

const parentIcon=(s:string)=>s.startsWith("Amazon Bedrock")||s==="Amazon Titan"?"Amazon Bedrock":s.startsWith("Amazon SageMaker")?"Amazon SageMaker AI":s.startsWith("Amazon S3")?"Amazon S3":s.startsWith("Amazon CloudWatch")?"Amazon CloudWatch":s.startsWith("IAM")?"AWS IAM":s==="AWS Lambda@Edge"?"AWS Lambda":s==="Elastic Load Balancing (ELB)"?"Elastic Load Balancing":s;

