const categoryConcepts:Record<string,string[]>={"Application Integration":["Messaging, routing and orchestration are different responsibilities.","Delivery semantics, retries, ordering and idempotency define production behavior.","Use durable buffers and explicit failure paths where consumers can fall behind."],"Compute":["Compute should remain replaceable; durable state belongs in data services.","Choose runtime based on control, duration, scaling, networking and latency needs.","Availability comes from multiple failure domains and health-aware traffic routing."],"Containers":["Registry, orchestrator, compute and application are separate layers.","Images are immutable; secrets and state stay outside containers.","Task/pod identity and autoscaling follow workload boundaries."],"Customer Engagement":["Channels, automation, business lookups and human escalation are separate layers.","Recordings/transcripts require independent retention and privacy controls.","AI assistance should augment contact flows without hiding deterministic business logic."],"Database":["Start with access patterns, consistency and failure requirements.","Read scaling, caching and indexing solve different problems.","Backups, replicas and multi-AZ deployment are not interchangeable recovery mechanisms."],"Developer Tools":["Developer tools belong to author/build/test/deploy/operate workflows rather than the application request path.","Use versioned artifacts and repeatable automation.","Prefer temporary credentials for automation and cross-account deployment."],"Machine Learning":["Separate data, retrieval, model inference, orchestration, tools and evaluation.","Quality, latency, safety and cost are measured independently.","Production AI needs identity, observability and durable state around the model call."],"Management and Governance":["Control-plane services span workloads and accounts rather than carrying application payloads.","Inventory, metrics, logs, audit and findings are distinct operational signals.","Automated remediation should remain auditable and bounded."],"Migration and Transfer":["Source, connectivity, transfer, verification and destination are separate layers.","Plan incremental sync and cutover instead of assuming one copy operation.","Throughput and protocol constraints drive tool selection."],"Networking and Content Delivery":["DNS, edge, routing, load balancing and private connectivity operate at different layers.","Security controls authorize traffic; routing determines path.","Multi-AZ or multi-Region designs need health-aware failover."],"Security, Identity, and Compliance":["Authentication, authorization, encryption, secrets and detection solve different controls.","Prefer temporary credentials and least privilege.","Findings need ownership, evidence and a remediation path."],"Storage":["Object, block and file storage expose different semantics.","Lifecycle policy should follow access frequency and recovery objectives.","Replication, versioning and backup solve different failure scenarios."]};

function PublicIcon({kind}:{kind:Kind}){const C=kind==="user"?Users:kind==="internet"?Globe2:kind==="data"?Database:kind==="security"?Shield:kind==="file"?FileText:kind==="network"?Network:kind==="storage"?HardDrive:kind==="ai"?BrainCircuit:kind==="message"?MessageSquare:kind==="monitor"?Activity:kind==="app"?Laptop:kind==="compute"?Server:Cloud;return <div className={`public-icon-disc public-${kind}`}><C size={34}/></div>}
function NodeView({node}:{node:Node}){if(node.kind)return <div className="v8-node public"><PublicIcon kind={node.kind}/><strong>{node.label}</strong><small>{node.sub}</small></div>;const icon=findAwsArchitectureIcon(node.icon||node.label);return <div className="v8-node aws">{icon?<div className="aws-icon-disc"><img src={awsIconSrc(icon)} data-fallback={awsIconFallbackSrc(icon)} onError={e=>{const el=e.currentTarget;const fallback=el.dataset.fallback;if(fallback&&el.src!==fallback){el.src=fallback;return}el.style.display="none";const next=el.parentElement?.nextElementSibling as HTMLElement|null;if(next)next.style.display="grid"}} alt={`${node.label} AWS architecture icon`}/></div>:null}<div className="public-icon-disc public-internet aws-safe-fallback" style={{display:icon?"none":"grid"}}><Cloud size={34}/></div><strong>{node.label}</strong><small>{node.sub}</small></div>}
function Architecture({arch,index}:{arch:Arch;index:number}){return <section className="v8-architecture" id={`architecture-${index}`} data-search-section="architectures"><div className="section-cap"><div><p>ARCHITECTURE {String(index).padStart(2,"0")}</p><h3>{arch.title}</h3></div><span>{arch.note}</span></div><div className="v8-reference">Reference pattern: {arch.reference}</div><div className="v8-layers">{arch.layers.map((layer,i)=><div className="v8-layer-wrap" key={i}><div className="v8-layer"><b className="v8-layer-title">{layer.title}</b><div className="v8-layer-nodes">{layer.nodes.map((n,j)=><NodeView key={j} node={n}/>)}</div></div>{i<arch.layers.length-1&&<div className="v8-connector" aria-hidden="true">→</div>}</div>)}</div></section>}
function Cards({title,items,id}:{title:string;items:string[];id?:string}){return <section className="knowledge-card" id={id}><div className="knowledge-card-title"><span>◆</span><h3>{title}</h3></div><div className="knowledge-card-body"><div className="concept-stack">{items.map((x,i)=><p key={i}><b>{String(i+1).padStart(2,"0")}</b>{x}</p>)}</div></div></section>}

export default function AipServiceLearningDetailsV8({serviceName,summary}:{serviceName:string;summary?:string}){const e=resolveEntry(serviceName);if(!e)return null;const arches=architectures(e.service,e.category);const concepts=categoryConcepts[e.category]||["Understand the service boundary and the layers around it.","Keep identity, data, operations and failure handling explicit.","Choose the service from its real operating model rather than its category name."];const useCases=arches.map(a=>`${a.title}: ${a.note}`);return <div className="service-knowledge aip-shared-learning aip-v8" data-service={e.service} data-search-scope="aws-service-learning"><div className="knowledge-intro"><div><p className="knowledge-kicker">VISUAL DEEP DIVE • {e.category.toUpperCase()}</p><h2>{e.service}</h2><p><b>What it is:</b> {summary||`A managed AWS capability in ${e.category}.`}</p></div><div className="knowledge-facts"><span><b>01</b>Purpose</span><span><b>02</b>Architecture</span><span><b>03</b>Operations</span><span><b>04</b>Exam fit</span></div></div><nav className="knowledge-jumps"><a href="#concepts">Concepts</a><a href="#architecture-1">Architectures</a><a href="#use-cases">Use cases</a><a href="#security">Security</a><a href="#cost-models">Cost</a><a href="#memory-hook">Exam hook</a></nav><div className="knowledge-grid" id="concepts"><Cards title="Core service concepts" items={concepts}/><Cards title="How to read the architecture" items={[`${e.service} is shown inside a complete multi-layer workload, not as an isolated source → service → destination pipeline.`,`Follow each example from users/data through identity or ingress, orchestration/processing, the service capability, durable state, and operations.`,`AWS nodes use the AWS architecture-icon resolver; non-AWS actors use coloured diagram-style icons and never render as blank boxes.`]}/></div>{arches.map((a,i)=><Architecture key={i} arch={a} index={i+1}/>)}<div className="knowledge-grid"><Cards id="use-cases" title="Practical use cases" items={useCases}/><Cards id="security" title="Security & governance" items={[`Apply least-privilege access at every layer that interacts with ${e.service}.`,`Encrypt sensitive data in transit and at rest where applicable; keep secrets outside application code.`,`Centralize authoritative audit and workload telemetry so architecture failures are diagnosable.`]}/><Cards title="Design & optimization" items={[`Scale the layer that is actually saturated instead of scaling every component together.`,`Keep synchronous request paths short; use events and queues where work can be asynchronous.`,`Design explicit retry, timeout, idempotency and recovery behavior around ${e.service}.`]}/><Cards id="cost-models" title="Cost model & drivers" items={[`Identify ${e.service}'s direct usage or provisioned-capacity driver.`,`Include downstream requests, data transfer, storage, logs and supporting compute in the architecture cost model.`,`Optimize architecture shape first—caching, batching, lifecycle, right-sizing or asynchronous processing often matters more than unit price.`]}/><Cards title="Service comparison" items={[`Choose ${e.service} when the scenario matches the operating boundary shown in the architectures above.`,`Compare adjacent services by responsibility, state model, invocation pattern, scaling behavior and network placement.`,`Reject exam options that force ${e.service} to own responsibilities handled by another layer in the architecture.`]}/><Cards id="memory-hook" title="Certification memory hook" items={[`Remember the full path around ${e.service}, not only the service logo.`,`Architecture 01 is a production reference pattern; Architecture 02 is an alternate or operational pattern${arches.length>2?"; Architecture 03 covers another important real-world variation":""}.`,`When evaluating an exam scenario, sketch these layers mentally: entry/identity → coordination → service capability → state/output → operations.`]}/></div></div>}
